PlantSupportTrellisPanelMaker.productStock = {}; PlantSupportTrellisPanelMaker.buildings = {}; PlantSupportTrellisPanelMaker.maker = nil; PlantSupportTrellisPanelMaker.activeMaking = {}; PlantSupportTrellisPanelMaker.totalProducts = 0; PlantSupportTrellisPanelMaker.dayTimer = 0
function PlantSupportTrellisPanelMaker.init() PlantSupportTrellisPanelMaker.ironStock=14; PlantSupportTrellisPanelMaker.bronzeStock=12; PlantSupportTrellisPanelMaker.woodStock=14; PlantSupportTrellisPanelMaker.leatherStock=8; PlantSupportTrellisPanelMaker.silverStock=8; PlantSupportTrellisPanelMaker.goldStock=6; PlantSupportTrellisPanelMaker.jewelStock=4; PlantSupportTrellisPanelMaker.pearlStock=4; PlantSupportTrellisPanelMaker.productStock={}; PlantSupportTrellisPanelMaker.buildings={}; PlantSupportTrellisPanelMaker.maker=nil; PlantSupportTrellisPanelMaker.activeMaking={}; PlantSupportTrellisPanelMaker.totalProducts=0; PlantSupportTrellisPanelMaker.dayTimer=0; print("[PlantSupportTrellisPanelMaker] Royal Plant Support Trellis Panel Maker System initialized (6 products, 4 buildings)") end
function PlantSupportTrellisPanelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlantSupportTrellisPanelMaker.maker={name=n or ("Panelnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Panelnik najet: %s (spretnost: %d)",PlantSupportTrellisPanelMaker.maker.name,s),"success") end; return true end
function PlantSupportTrellisPanelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlantSupportTrellisPanelMaker.build(id) local ok,e=PlantSupportTrellisPanelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlantSupportTrellisPanelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlantSupportTrellisPanelMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlantSupportTrellisPanelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlantSupportTrellisPanelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PlantSupportTrellisPanelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PlantSupportTrellisPanelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PlantSupportTrellisPanelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PlantSupportTrellisPanelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PlantSupportTrellisPanelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlantSupportTrellisPanelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlantSupportTrellisPanelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlantSupportTrellisPanelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlantSupportTrellisPanelMaker.buildings==0 then return false,"Potrebna panelna delavnica" end; if not PlantSupportTrellisPanelMaker.maker then return false,"Potreben panelnik" end; return true end
function PlantSupportTrellisPanelMaker.make(pt,qty) qty=qty or 1; local ok,e=PlantSupportTrellisPanelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PlantSupportTrellisPanelMaker.ironStock=PlantSupportTrellisPanelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PlantSupportTrellisPanelMaker.bronzeStock=PlantSupportTrellisPanelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PlantSupportTrellisPanelMaker.woodStock=PlantSupportTrellisPanelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PlantSupportTrellisPanelMaker.leatherStock=PlantSupportTrellisPanelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PlantSupportTrellisPanelMaker.silverStock=PlantSupportTrellisPanelMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlantSupportTrellisPanelMaker.goldStock=PlantSupportTrellisPanelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlantSupportTrellisPanelMaker.jewelStock=PlantSupportTrellisPanelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlantSupportTrellisPanelMaker.pearlStock=PlantSupportTrellisPanelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlantSupportTrellisPanelMaker.maker then t=math.max(1,t-math.floor(PlantSupportTrellisPanelMaker.maker.skill/13)) end; table.insert(PlantSupportTrellisPanelMaker.activeMaking,{id="plantsupporttrellispanel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlantSupportTrellisPanelMaker.completeMaking(m) local q=1.0+(PlantSupportTrellisPanelMaker.getQualityBonus()/100); if PlantSupportTrellisPanelMaker.maker then q=q+(PlantSupportTrellisPanelMaker.maker.skill/140) end; q=math.min(2.5,q); PlantSupportTrellisPanelMaker.productStock[m.productType]=(PlantSupportTrellisPanelMaker.productStock[m.productType] or 0)+m.quantity; PlantSupportTrellisPanelMaker.totalProducts=PlantSupportTrellisPanelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlantSupportTrellisPanelMaker.maker then PlantSupportTrellisPanelMaker.maker.itemsMade=PlantSupportTrellisPanelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlantSupportTrellisPanelMaker.maker.skill=math.min(100,PlantSupportTrellisPanelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Panel izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"plantsupporttrellispanel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PlantSupportTrellisPanelMaker.update(dt) if not _G.state then return end; PlantSupportTrellisPanelMaker.dayTimer=PlantSupportTrellisPanelMaker.dayTimer+dt; if PlantSupportTrellisPanelMaker.dayTimer>=30 then PlantSupportTrellisPanelMaker.dayTimer=0; for i=#PlantSupportTrellisPanelMaker.activeMaking,1,-1 do local m=PlantSupportTrellisPanelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlantSupportTrellisPanelMaker.completeMaking(m); table.remove(PlantSupportTrellisPanelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlantSupportTrellisPanelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlantSupportTrellisPanelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlantSupportTrellisPanelMaker.getStats() return {ironStock=PlantSupportTrellisPanelMaker.ironStock,bronzeStock=PlantSupportTrellisPanelMaker.bronzeStock,woodStock=PlantSupportTrellisPanelMaker.woodStock,leatherStock=PlantSupportTrellisPanelMaker.leatherStock,silverStock=PlantSupportTrellisPanelMaker.silverStock,goldStock=PlantSupportTrellisPanelMaker.goldStock,jewelStock=PlantSupportTrellisPanelMaker.jewelStock,pearlStock=PlantSupportTrellisPanelMaker.pearlStock,productStock=PlantSupportTrellisPanelMaker.productStock,numBuildings=#PlantSupportTrellisPanelMaker.buildings,hasMaker=PlantSupportTrellisPanelMaker.maker~=nil,makerName=PlantSupportTrellisPanelMaker.maker and PlantSupportTrellisPanelMaker.maker.name or "—",makerSkill=PlantSupportTrellisPanelMaker.maker and PlantSupportTrellisPanelMaker.maker.skill or 0,activeMaking=#PlantSupportTrellisPanelMaker.activeMaking,totalProducts=PlantSupportTrellisPanelMaker.totalProducts} end
